mapper.select:
SELECT
    id, code, title, suiteRoom, suiteHall, suiteBathroom, area, direction, floor, totalFloor, birth,
    housebelong, price, decoration, property, propertyrights, salesman, housestatus,
    detailed_address, contact_wechat, highlights, rental_reqs, description
FROM t_houseinformation


        AND code LIKE CONCAT(CONCAT('%', #{houseInfo.code}, '%'))


        AND title LIKE CONCAT(CONCAT('%', #{houseInfo.title}, '%'))


        AND suiteRoom = #{houseInfo.suiteRoom}


        AND suiteHall = #{houseInfo.suiteHall}


        AND suiteBathroom = #{houseInfo.suiteBathroom}


        AND area LIKE CONCAT(CONCAT('%', #{houseInfo.area}, '%'))


        AND direction = #{houseInfo.direction}


        AND floor = #{houseInfo.floor}


        AND totalFloor = #{houseInfo.totalFloor}


        AND birth = #{houseInfo.birth}


        AND housebelong = #{houseInfo.housebelong}


        AND price = #{houseInfo.price}


        AND decoration = #{houseInfo.decoration}


        AND property = #{houseInfo.property}


        AND propertyrights = #{houseInfo.propertyrights}


        AND salesman = #{houseInfo.salesman}


        AND housestatus = #{houseInfo.housestatus}


ORDER BY id DESC

SELECT
    id, code, title, suiteRoom, suiteHall, suiteBathroom, area, direction, floor, totalFloor, birth,
    housebelong, price, decoration, property, propertyrights, salesman, housestatus,
    detailed_address, contact_wechat, highlights, rental_reqs, description
FROM t_houseinformation


        AND housebelong = #{houseInfo.housebelong}


        AND suiteRoom = #{houseInfo.suiteRoom}


        AND direction = #{houseInfo.direction}


        AND decoration = #{houseInfo.decoration}


        AND property = #{houseInfo.property}


        AND propertyrights = #{houseInfo.propertyrights}


        AND housestatus = #{houseInfo.housestatus}


        AND floor = #{houseInfo.floor}


        AND totalFloor = #{houseInfo.totalFloor}

    AND area BETWEEN #{rangeInfo.minArea} AND #{rangeInfo.maxArea}
    AND birth BETWEEN #{rangeInfo.minBirth} AND #{rangeInfo.maxBirth}
    AND price BETWEEN #{rangeInfo.minPrice} AND #{rangeInfo.maxPrice}

ORDER BY id DESC

SELECT h.id
FROM t_houseinformation h


        AND h.housebelong = #{houseInfo.housebelong}


        AND h.suiteRoom = #{houseInfo.suiteRoom}


        AND h.direction = #{houseInfo.direction}


        AND h.decoration = #{houseInfo.decoration}


        AND h.property = #{houseInfo.property}


        AND h.propertyrights = #{houseInfo.propertyrights}


        AND h.housestatus = #{houseInfo.housestatus}


        AND h.floor = #{houseInfo.floor}


        AND h.totalFloor = #{houseInfo.totalFloor}

    AND h.area BETWEEN #{rangeInfo.minArea} AND #{rangeInfo.maxArea}
    AND h.birth BETWEEN #{rangeInfo.minBirth} AND #{rangeInfo.maxBirth}
    AND h.price BETWEEN #{rangeInfo.minPrice} AND #{rangeInfo.maxPrice}

ORDER BY h.id DESC
LIMIT #{maxIds}

SELECT hp.code, hp.photocode, ti.savingfilename, ti.originalfilename, ti.contenttype FROM t_housephoto hp JOIN t_img ti ON hp.photocode = ti.photocode JOIN ( SELECT code, MIN(photocode) AS photocode FROM t_housephoto WHERE code IN
#{code}
GROUP BY code ) t ON hp.code = t.code AND hp.photocode = t.photocode ORDER BY hp.code
